/**
 * flagRegistry — the DECLARATIVE gate registry.
 *
 *
 * ONE typed table for every runtime env flag the source reads — the
 * `MERCURY_*` name, polarity KIND, summary, OFF-contract, and primary
 * consumer. Call sites and env writes use the registered spelling, and
 * `flagEnv` is the ONE bounded reader. The anti-drift anchor is mechanical:
 * scripts/substrate/prove-flag-registry.ts re-extracts every env read from
 * src and FAILS on any flag missing here (or any polarity that does not
 * match the read pattern), so the registry can never silently trail the
 * code. THIS table is the one source of truth; a readable render is
 * generated on demand (scripts/substrate/gen-flag-table.ts → untracked
 * scripts/substrate/.out/).
 *
 * KINDS:
 *   'default-on' — default-ON, `=0` disables (the
 *                    standard substrate polarity; OFF ⇒ the row's contract).
 *   'opt-in'       — default-OFF everywhere, `=1` enables.
 *   'value'        — carries a value (model id, ms, path); not a boolean gate.
 *   'mixed'        — deliberately dual-polarity at distinct sites (e.g.
 *                    MERCURY_BRIEF: headless suppress vs explicit opt-in).
 *
 * {@link flagEnabled} answers the two GATE kinds with a LIVE env read on every
 * call — the authority-toggles invariant (a toggle is only honest if the gate
 * re-reads env live) holds by construction. Gate helpers
 * (daemonFeatureGates) delegate here: their POLICY is now data.
 */


export type FlagKind = 'default-on' | 'opt-in' | 'value' | 'mixed'

/**
 * GRADUATION TIER — the evidence bar a DEFAULT-FLIP of a gate flag must clear
 * (the methodological ladder; enforced by prove-flag-registry):
 *
 *   'display'    — presentation only (a chip, a rail, a banner). Flip bar:
 *                  proof green + render-verify @80/120.
 *   'additive'   — records/preserves MORE (an artifact, a ledger row, a
 *                  handoff note) and never changes a decision, a prompt the
 *                  model acts on, or what gets refused. Worst case = status
 *                  quo. Flip bar: proof green + a written failure-mode note
 *                  (the verbatim-tail precedent). A flag whose behavioral
 *                  consent lives at the CALL SITE (e.g. workflow tier routing
 *                  — the script declares tier, the flag is only the kill)
 *                  also sits here; say so in the summary.
 *   'behavioral' — changes model-visible prompts, routing, thresholds, or
 *                  what gets stored/refused. Flip bar: a NUMBER — a held-out
 *                  A/B, a replay benchmark, or an executable proof of the
 *                  policy, committed and named in `evidence` (the flip-verdict
 *                  precedent). A `default-on` behavioral row WITHOUT an
 *                  `evidence` file fails the registry proof.
 *   'security'   — permission/trust posture. Never auto-flipped: an explicit
 *                  operator decision with a threat-model note.
 *   'infra'      — plumbing: capability enables, role markers, engage keys.
 *                  Not a graduation subject.
 *
 * Tiers are REQUIRED on the two gate kinds ('default-on' | 'opt-in') and
 * meaningless on 'value'/'mixed' knobs (leave them off there).
 */
export type FlagTier = 'display' | 'additive' | 'behavioral' | 'security' | 'infra'

export interface FlagSpec {
  /** The env spelling. */
  env: string
  kind: FlagKind
  summary: string
  /** What OFF (or unset, per kind) means — the documented contract. */
  off: string
  /** Primary consumer (first read site; others may exist). */
  consumer: string
  /** Graduation tier (REQUIRED for gate kinds — see FlagTier). */
  tier?: FlagTier
  /** Committed evidence artifact backing a default-ON behavioral gate
   *  (repo-relative path; prove-flag-registry asserts it exists). */
  evidence?: string
 /** Interaction metadata — REQUIRED on every interacting flag
   *  (the registry proof enforces reference existence + symmetry, and the
   *  flag-interaction sweep runs the constrained vectors). */
  requires?: string[]
  excludes?: string[]
  interactsWith?: string[]
  /** When/how this flag retires: a date, a condition, or 'permanent'. */
  retirement?: string
  /** The consumer runs BEFORE the runtime boots (the standalone
   * splash asset / the generated launchers) — liveness reads the asset
   * file instead of src, and the dist sweep covers those files too. */
  preBoot?: true
  /** Mercury stamps this variable on its OWN writes (process identity the
   *  product asserts about itself, inherited by children) — a present
   *  value is not an operator override, and the doctor's env-overrides
   *  count must not read it as one (FC-138). */
  selfStamped?: true
}

