const byEnv = new Map<string, FlagSpec>()
for (const f of FLAG_REGISTRY) byEnv.set(f.env, f)

export function getFlagSpec(env: string): FlagSpec | undefined {
  return byEnv.get(env)
}

/**
 * THE bounded env reader for the flag estate: the LIVE raw value of a
 * registered flag. Throws on an unregistered flag (register first — the
 * registry proof enforces it anyway).
 */
export function flagEnv(env: string): string | undefined {
  const spec = byEnv.get(env)
  if (!spec) throw new Error(`flagEnv: unregistered flag ${env} — add it to FLAG_REGISTRY`)
  return process.env[spec.env]
}

/**
 * Tolerant variant of {@link flagEnv} for GENERIC env helpers (envInt-style
 * readers that also serve unregistered names): a registered name resolves
 * through the registry reader; an unregistered name falls back to a raw live
 * read of exactly that spelling.
 */
export function flagEnvLoose(env: string): string | undefined {
  return byEnv.has(env) ? flagEnv(env) : process.env[env]
}

/**
 * LIVE boolean gate for the two gate kinds. Throws on a non-gate row (value /
 * mixed flags have bespoke read sites — using this for them would be a bug) and
 * on an unregistered flag (register first; the proof enforces it anyway).
 */
export function flagEnabled(env: string): boolean {
  const spec = byEnv.get(env)
  if (!spec) throw new Error(`flagEnabled: unregistered flag ${env} — add it to FLAG_REGISTRY`)
  switch (spec.kind) {
    case 'default-on': {
      // The OFF vocabulary is envUtils' isEnvDefinedFalsy — 0 · false · no ·
      // off, case-folded and trimmed — inlined because envUtils imports this
      // module; stray surrounding quotes (the Windows set VAR="0" form) are
      // stripped first. The old exact-byte '0' compare failed OPEN on every
      // other falsy spelling, which for security-tier rows silently left the
      // door open (FC-006). Junk still reads ON: junk-to-off would silently
      // disarm a default-on feature.
      const raw = flagEnv(spec.env)
      if (typeof raw === 'string') {
        const folded = raw.replace(/^["']+|["']+$/g, '').trim().toLowerCase()
        if (folded === '0' || folded === 'false' || folded === 'no' || folded === 'off') return false
      }
      return true
    }
    case 'opt-in':
      return flagEnv(spec.env) === '1'
    default:
      throw new Error(`flagEnabled: ${env} is a ${spec.kind} flag — read its value at its consumer`)
  }
}

/**
 * THE bounded env WRITER: set a registered flag in this process's
 * environment. Throws on an unregistered flag, so an in-process write can
 * never mint a spelling the reader does not know.
 */
export function setFlagEnv(env: string, value: string): void {
  const spec = byEnv.get(env)
  if (!spec) throw new Error(`setFlagEnv: unregistered flag ${env} — add it to FLAG_REGISTRY`)
  process.env[spec.env] = value
}

/** The paired delete: removes a registered flag from this process's env. */
export function deleteFlagEnv(env: string): void {
  const spec = byEnv.get(env)
  if (!spec) throw new Error(`deleteFlagEnv: unregistered flag ${env} — add it to FLAG_REGISTRY`)
  delete process.env[spec.env]
}

/** The registered spelling of a flag as a one-element list — env scrubbers
 *  and stampers iterate it and get the registration check for free. */
export function flagSpellings(env: string): string[] {
  const spec = byEnv.get(env)
  if (!spec) throw new Error(`flagSpellings: unregistered flag ${env} — add it to FLAG_REGISTRY`)
  return [spec.env]
}

/** Stamp a registered flag onto a CHILD env object (the object-env twin of
 *  setFlagEnv). */
export function stampFlagOnEnv(
  env: Record<string, string | undefined>,
  name: string,
  value: string,
): void {
  for (const spelling of flagSpellings(name)) env[spelling] = value
}

/** A registered flag as a spread-ready env fragment. */
export function flagPair(name: string, value: string): Record<string, string> {
  const out: Record<string, string> = {}
  for (const spelling of flagSpellings(name)) out[spelling] = value
  return out
}
